<form class="aics-wizard-form" data-operation="generate_article"><header class="aics-wizard-step-header"><p class="aics-eyebrow"><?php esc_html_e('Step 2 of 6','ai-content-studio');?></p><h2 tabindex="-1"><?php esc_html_e('Choose an Idea','ai-content-studio');?></h2><p><?php esc_html_e('Select one direction to develop into a full article.','ai-content-studio');?></p></header><div class="aics-wizard-idea-grid"><?php foreach($ideas as $idea):$id=(string)($idea['id']??'');?><label class="aics-wizard-idea"><input type="radio" name="selected_idea_id" value="<?php echo esc_attr($id);?>" <?php checked(($selected['id']??'')===$id);?> required><span><strong><?php echo esc_html($idea['title']??'');?></strong><small><?php echo esc_html($idea['description']??'');?></small><em><?php echo esc_html($idea['primary_keyword']??'');?></em></span></label><?php endforeach;?></div><footer class="aics-wizard-actions"><button class="button" type="button" data-aics-step="context"><?php esc_html_e('Back','ai-content-studio');?></button><button class="button aics-button-danger" type="button" data-aics-regenerate="ideas"><?php esc_html_e('Regenerate Ideas','ai-content-studio');?></button><button class="button button-primary" type="submit"><?php esc_html_e('Next: Generate Article','ai-content-studio');?></button></footer></form>
